/**
 * @suppress
 */
public object FfiConverterTypePushManager: FfiConverter<PushManager, Long> {
    override fun lower(value: PushManager): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): PushManager {
        return PushManager(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): PushManager {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: PushManager) = 8UL

    override fun write(value: PushManager, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



