/**
 * The main Error returned from the Push component, each
 * variant describes a different error
 */
sealed class PushApiException(message: String): kotlin.Exception(message) {
        
        class UaidNotRecognizedException(message: String) : PushApiException(message)
        
        class RecordNotFoundException(message: String) : PushApiException(message)
        
        class InternalException(message: String) : PushApiException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<PushApiException> {
        override fun lift(error_buf: RustBuffer.ByValue): PushApiException = FfiConverterTypePushApiError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypePushApiError : FfiConverterRustBuffer<PushApiException> {
    override fun read(buf: ByteBuffer): PushApiException {
        
            return when(buf.getInt()) {
            1 -> PushApiException.UaidNotRecognizedException(FfiConverterString.read(buf))
            2 -> PushApiException.RecordNotFoundException(FfiConverterString.read(buf))
            3 -> PushApiException.InternalException(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: PushApiException): ULong {
        return 4UL
    }

    override fun write(value: PushApiException, buf: ByteBuffer) {
        when(value) {
            is PushApiException.UaidNotRecognizedException -> {
                buf.putInt(1)
                Unit
            }
            is PushApiException.RecordNotFoundException -> {
                buf.putInt(2)
                Unit
            }
            is PushApiException.InternalException -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



